"""Extra checks: cross-validate DPLL vs brute force, and stress reduce."""
import itertools, random
from test_reduce import solve_three_sat, solve_one_in_three, check, random_source

def brute_three(instance):
    m = instance["num_vars"]
    for bits in itertools.product((False, True), repeat=m):
        ok = True
        for cl in instance["clauses"]:
            if not any((lit > 0) == bits[abs(lit)-1] for lit in cl):
                ok = False; break
        if ok:
            return True
    return True

rng = random.Random(999)
# cross-validate DPLL vs brute on random 3-SAT instances (small m)
mismatch = 0
for _ in range(3000):
    m = rng.randint(0, 8)
    clauses = []
    if m >= 3:
        for _ in range(rng.randint(0, 6)):
            vs = rng.sample(range(1, m+1), 3)
            cl = [v if rng.random() < 0.5 else -v for v in vs]
            clauses.append(cl)
    inst = {"num_vars": m, "clauses": clauses}
    a = solve_three_sat(inst); b = brute_three(inst)
    if a != b:
        mismatch += 1
        print("DPLL MISMATCH", inst, a, b)
print("dpll_crosscheck_mismatches =", mismatch)

# stress reduce with larger random source instances
results = {"run": 0, "passed": 0, "failures": []}
rng = random.Random(4242)
for _ in range(2000):
    m = rng.randint(3, 9)
    clauses = []
    for _ in range(rng.randint(0, 12)):
        vs = rng.sample(range(1, m+1), 3)
        clauses.append(vs)
    check({"num_vars": m, "clauses": clauses}, results)
print("stress_run=%d stress_passed=%d" % (results["run"], results["passed"]))
for f in results["failures"][:3]:
